from dataclasses import dataclass


@dataclass(frozen=True, slots=True, kw_only=True)
class Product:
    product_id: int
    name: str


class ProductService:
    async def get_product(self, product_id: int) -> Product:
        return Product(product_id=product_id, name="lamp")
